customMethods.script:
# ONE entry point for every action on this popup. Each is a thin call; the procs
# decide. Everything runs as the Quality sign-in user (the popup is opened through
# Common.Session.requireElevation).
v = self.view
S = BlueRidge.Common.Session
if not S.isElevated(self.session):
	BlueRidge.Common.Notify.toast("Sign-in ended", "Your Quality sign-in has ended. Close this and open Repack again.", "warning")
	return
if v.custom.busy:
	return
v.custom.busy = True
try:
	RW = BlueRidge.Lots.ContainerRework
	uid = self.session.custom.appUserId
	tid = v.params.terminalLocationId
	cid = v.params.containerId
	info = v.custom.info
	serialized = bool(info.IsSerialized)
	tray = v.custom.selectedTrayId
	serial = v.custom.selectedSerialId if serialized else None
	qty = 1 if serialized else v.custom.quantity
	if kind in ("scrap", "apply", "move") and tray is None:
		BlueRidge.Common.Notify.toast("Pick a tray", "Select the serial to work on." if serialized else "Select the tray the parts come out of.", "warning")
		return
	if kind == "open":
		res = RW.open(cid, uid, tid)
	elif kind == "filling":
		res = RW.setStage(cid, "Filling", None, uid, tid)
	elif kind == "processing":
		res = RW.setStage(cid, "Processing", None, uid, tid)
	elif kind == "send":
		res = RW.setStage(cid, "Filling", v.custom.lineId, uid, tid)
	elif kind == "complete":
		res = RW.completeHere(cid, uid, tid)
	elif kind == "void":
		res = RW.void(cid, v.custom.remarks, uid, tid)
	elif kind == "scrap":
		res = RW.scrap(tray, v.custom.defectCodeId, qty, serial, v.custom.remarks, uid, tid)
	elif kind == "apply":
		res = RW.applyRecordedScrap(tray, v.custom.intentId, serial, uid, tid)
	elif kind == "move":
		res = RW.move(tray, v.custom.targetId, qty, serial, uid, tid)
	else:
		res = {"Status": 0, "Message": "Unknown action."}
	BlueRidge.Common.Ui.notifyResult(res, "Container %s" % cid, (res or {}).get("Message"))
	if res and res.get("Status"):
		v.custom.quantity = ""
		v.custom.intentId = None
		v.custom.selectedSerialId = None
		if kind in ("void", "complete"):
			v.custom.remarks = ""
		v.custom.token = (v.custom.token or 0) + 1
		system.perspective.sendMessage("controlledRunChanged", payload={"containerId": cid}, scope="page")
finally:
	v.custom.busy = False

messageHandlers.script:
v = self.view
p = payload or {}
if v.custom.selectedSerialId == p.get("serialId"):
	v.custom.selectedSerialId = None
	v.custom.selectedTrayId = None
else:
	v.custom.selectedSerialId = p.get("serialId")
	v.custom.selectedTrayId = p.get("trayId")
